MARKET_FEATURES = len(ALL_RAW_FEATURES) + len(ENGINEERED_FEATURE_NAMES)
ACCOUNT_FEATURES = len(ACCOUNT_FEATURE_NAMES)
TOTAL_FEATURES = MARKET_FEATURES + ACCOUNT_FEATURES
FEATURE_COLUMNS = ALL_RAW_FEATURES + ENGINEERED_FEATURE_NAMES + ACCOUNT_FEATURE_NAMES

